object AcDerIecCodec {

    const val EXI_HEADER: Byte = 0x80.toByte()

    /** Generous upper bound; encode() returns a right-sized copy. */
    private const val MAX_MESSAGE_BYTES = 65536

    fun encode(msg: AC_ChargeParameterDiscoveryReq): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(4u, 6)   // document element selector
        encodeAC_ChargeParameterDiscoveryReq(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun encode(msg: AC_ChargeParameterDiscoveryRes): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(5u, 6)   // document element selector
        encodeAC_ChargeParameterDiscoveryRes(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun encode(msg: AC_ChargeLoopReq): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(2u, 6)   // document element selector
        encodeAC_ChargeLoopReq(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun encode(msg: AC_ChargeLoopRes): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(3u, 6)   // document element selector
        encodeAC_ChargeLoopRes(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun encode(msg: AC_CPDReqEnergyTransferMode): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(0u, 6)   // document element selector
        encodeAC_CPDReqEnergyTransferMode(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun encode(msg: AC_CPDResEnergyTransferMode): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(1u, 6)   // document element selector
        encodeAC_CPDResEnergyTransferMode(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun decodeAny(src: ByteArray): Any {
        require(src.isNotEmpty() && src[0] == EXI_HEADER) { "Invalid EXI header." }
        val r = BitReader(src, 1)
        return when (val sel = r.readBits(6)) {
            4u -> decodeAC_ChargeParameterDiscoveryReq(r)
            5u -> decodeAC_ChargeParameterDiscoveryRes(r)
            2u -> decodeAC_ChargeLoopReq(r)
            3u -> decodeAC_ChargeLoopRes(r)
            0u -> decodeAC_CPDReqEnergyTransferMode(r)
            1u -> decodeAC_CPDResEnergyTransferMode(r)
            else -> throw IllegalArgumentException("Unknown document index $sel.")
        }
    }

    private fun encodeAC_ChargeParameterDiscoveryReqType(w: BitWriter, msg: AC_ChargeParameterDiscoveryReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        when (val v = msg.aC_CPDReqEnergyTransferMode) {
            is BPT_AC_CPDReqEnergyTransferModeType -> {
                w.writeBits(1u, 2)   // BPT_AC_CPDReqEnergyTransferMode
                encodeBPT_AC_CPDReqEnergyTransferModeType(w, v)
            }
            is DER_AC_CPDReqEnergyTransferModeType -> {
                w.writeBits(2u, 2)   // DER_AC_CPDReqEnergyTransferMode
                encodeDER_AC_CPDReqEnergyTransferModeType(w, v)
            }
            is AC_CPDReqEnergyTransferModeType -> {
                w.writeBits(0u, 2)   // AC_CPDReqEnergyTransferMode
                encodeAC_CPDReqEnergyTransferModeType(w, v)
            }
            else -> throw IllegalArgumentException("unsupported substitution member for AC_CPDReqEnergyTransferMode")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAC_ChargeParameterDiscoveryReqType(r: BitReader): AC_ChargeParameterDiscoveryReqType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        val _aC_CPDReqEnergyTransferMode: AC_CPDReqEnergyTransferModeType = when (r.readBits(2)) {
            0u -> decodeAC_CPDReqEnergyTransferModeType(r)
            1u -> decodeBPT_AC_CPDReqEnergyTransferModeType(r)
            2u -> decodeDER_AC_CPDReqEnergyTransferModeType(r)
            else -> throw IllegalArgumentException("unknown substitution index")
        }
        r.readBits(1)   // element EE
        return AC_ChargeParameterDiscoveryReqType(_header, _aC_CPDReqEnergyTransferMode)
    }

    private fun encodeAC_ChargeParameterDiscoveryResType(w: BitWriter, msg: AC_ChargeParameterDiscoveryResType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        when (val v = msg.aC_CPDResEnergyTransferMode) {
            is BPT_AC_CPDResEnergyTransferModeType -> {
                w.writeBits(1u, 2)   // BPT_AC_CPDResEnergyTransferMode
                encodeBPT_AC_CPDResEnergyTransferModeType(w, v)
            }
            is DER_AC_CPDResEnergyTransferModeType -> {
                w.writeBits(2u, 2)   // DER_AC_CPDResEnergyTransferMode
                encodeDER_AC_CPDResEnergyTransferModeType(w, v)
            }
            is AC_CPDResEnergyTransferModeType -> {
                w.writeBits(0u, 2)   // AC_CPDResEnergyTransferMode
                encodeAC_CPDResEnergyTransferModeType(w, v)
            }
            else -> throw IllegalArgumentException("unsupported substitution member for AC_CPDResEnergyTransferMode")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAC_ChargeParameterDiscoveryResType(r: BitReader): AC_ChargeParameterDiscoveryResType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _responseCode = ResponseCode.entries[r.readBits(6).toInt()]
        r.readBits(1)   // child EE
        val _aC_CPDResEnergyTransferMode: AC_CPDResEnergyTransferModeType = when (r.readBits(2)) {
            0u -> decodeAC_CPDResEnergyTransferModeType(r)
            1u -> decodeBPT_AC_CPDResEnergyTransferModeType(r)
            2u -> decodeDER_AC_CPDResEnergyTransferModeType(r)
            else -> throw IllegalArgumentException("unknown substitution index")
        }
        r.readBits(1)   // element EE
        return AC_ChargeParameterDiscoveryResType(_header, _responseCode, _aC_CPDResEnergyTransferMode)
    }

    private fun encodeAC_ChargeLoopReqType(w: BitWriter, msg: AC_ChargeLoopReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        var st0 = 0
        var done0 = false
        while (!done0) {
            when (st0) {
                0 -> {
                    if (msg.displayParameters != null) {
                        w.writeBits(0u, 2)   // DisplayParameters
                        encodeDisplayParametersType(w, msg.displayParameters!!)
                        st0 = 1
                    } else {
                        w.writeBits(1u, 2)   // SE(MeterInfoRequested)
                        w.writeBits(0u, 1)   // value-start
                        w.writeBits(if (msg.meterInfoRequested) 1u else 0u, 1)
                        w.writeBits(0u, 1)   // child EE
                        done0 = true
                    }
                }
                1 -> {
                    w.writeBits(0u, 1)   // SE(MeterInfoRequested)
                    w.writeBits(0u, 1)   // value-start
                    w.writeBits(if (msg.meterInfoRequested) 1u else 0u, 1)
                    w.writeBits(0u, 1)   // child EE
                    done0 = true
                }
            }
        }
        when (val v = msg.cLReqControlMode) {
            is BPT_Dynamic_AC_CLReqControlModeType -> {
                w.writeBits(0u, 3)   // BPT_Dynamic_AC_CLReqControlMode
                encodeBPT_Dynamic_AC_CLReqControlModeType(w, v)
            }
            is BPT_Scheduled_AC_CLReqControlModeType -> {
                w.writeBits(1u, 3)   // BPT_Scheduled_AC_CLReqControlMode
                encodeBPT_Scheduled_AC_CLReqControlModeType(w, v)
            }
            is DER_Dynamic_AC_CLReqControlModeType -> {
                w.writeBits(3u, 3)   // DER_Dynamic_AC_CLReqControlMode
                encodeDER_Dynamic_AC_CLReqControlModeType(w, v)
            }
            is DER_Scheduled_AC_CLReqControlModeType -> {
                w.writeBits(4u, 3)   // DER_Scheduled_AC_CLReqControlMode
                encodeDER_Scheduled_AC_CLReqControlModeType(w, v)
            }
            is Dynamic_AC_CLReqControlModeType -> {
                w.writeBits(5u, 3)   // Dynamic_AC_CLReqControlMode
                encodeDynamic_AC_CLReqControlModeType(w, v)
            }
            is Scheduled_AC_CLReqControlModeType -> {
                w.writeBits(6u, 3)   // Scheduled_AC_CLReqControlMode
                encodeScheduled_AC_CLReqControlModeType(w, v)
            }
            else -> throw IllegalArgumentException("unsupported substitution member for CLReqControlMode")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAC_ChargeLoopReqType(r: BitReader): AC_ChargeLoopReqType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        var _displayParameters: DisplayParametersType? = null
        var _meterInfoRequested: Boolean? = null
        var st1 = 0
        var done1 = false
        while (!done1) {
            when (st1) {
                0 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _displayParameters = decodeDisplayParametersType(r)
                            st1 = 1
                        }
                        1u -> {   // SE(MeterInfoRequested)
                            r.readBits(1)   // value-start
                            _meterInfoRequested = r.readBits(1).toInt() != 0
                            r.readBits(1)   // child EE
                            done1 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                1 -> {
                    when (r.readBits(1)) {
                        0u -> {   // SE(MeterInfoRequested)
                            r.readBits(1)   // value-start
                            _meterInfoRequested = r.readBits(1).toInt() != 0
                            r.readBits(1)   // child EE
                            done1 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
            }
        }
        val _cLReqControlMode: CLReqControlModeType = when (r.readBits(3)) {
            0u -> decodeBPT_Dynamic_AC_CLReqControlModeType(r)
            1u -> decodeBPT_Scheduled_AC_CLReqControlModeType(r)
            2u -> throw IllegalArgumentException("abstract substitution head cannot be decoded")
            3u -> decodeDER_Dynamic_AC_CLReqControlModeType(r)
            4u -> decodeDER_Scheduled_AC_CLReqControlModeType(r)
            5u -> decodeDynamic_AC_CLReqControlModeType(r)
            6u -> decodeScheduled_AC_CLReqControlModeType(r)
            else -> throw IllegalArgumentException("unknown substitution index")
        }
        r.readBits(1)   // element EE
        return AC_ChargeLoopReqType(_header, _displayParameters, _meterInfoRequested!!, _cLReqControlMode)
    }

    private fun encodeAC_ChargeLoopResType(w: BitWriter, msg: AC_ChargeLoopResType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        var st2 = 0
        var done2 = false
        while (!done2) {
            when (st2) {
                0 -> {
                    val sub_cLResControlMode = msg.cLResControlMode
                    if (msg.eVSEStatus != null) {
                        w.writeBits(0u, 4)   // EVSEStatus
                        encodeEVSEStatusType(w, msg.eVSEStatus!!)
                        st2 = 1
                    } else if (msg.meterInfo != null) {
                        w.writeBits(1u, 4)   // MeterInfo
                        encodeMeterInfoType(w, msg.meterInfo!!)
                        st2 = 2
                    } else if (msg.receipt != null) {
                        w.writeBits(2u, 4)   // Receipt
                        encodeReceiptType(w, msg.receipt!!)
                        st2 = 3
                    } else if (msg.eVSETargetFrequency != null) {
                        w.writeBits(3u, 4)   // EVSETargetFrequency
                        encodeRationalNumberType(w, msg.eVSETargetFrequency!!)
                        st2 = 4
                    } else if (sub_cLResControlMode is BPT_Dynamic_AC_CLResControlModeType) {
                        w.writeBits(4u, 4)   // BPT_Dynamic_AC_CLResControlMode
                        encodeBPT_Dynamic_AC_CLResControlModeType(w, sub_cLResControlMode)
                        done2 = true
                    } else if (sub_cLResControlMode is BPT_Scheduled_AC_CLResControlModeType) {
                        w.writeBits(5u, 4)   // BPT_Scheduled_AC_CLResControlMode
                        encodeBPT_Scheduled_AC_CLResControlModeType(w, sub_cLResControlMode)
                        done2 = true
                    } else if (sub_cLResControlMode is DER_Dynamic_AC_CLResControlModeType) {
                        w.writeBits(7u, 4)   // DER_Dynamic_AC_CLResControlMode
